sys_script_include.script:
function RecordTransporterPackageCatalogTopics(vPackage, query) {

    var grPackage = RecordTransporterGetPackageRecord(vPackage);
    if (IsValidRecord(grPackage) == false) {
        return false;
    }

    var strPackageScope = GetStringValue(grPackage.sys_scope);

    var topicsSysIds = {};

    var grCatItem = new GlideRecord('sc_cat_item');
    grCatItem.addQuery('sys_scope', strPackageScope);
    GlideRecordAddQuery(grCatItem, query);
    grCatItem.query();

    while (grCatItem.next()) {
        var strCatItemSysId = GetStringValue(grCatItem.sys_id);

        var grM2M = new GlideRecord('m2m_connected_content');
        grM2M.addQuery('catalog_item', strCatItemSysId);
        grM2M.query();

        while (grM2M.next()) {
            RecordTransporterRecordPack(grPackage, grM2M);

            var strTopicSysId = GetStringValue(grM2M.topic);
            if (strTopicSysId) {
                topicsSysIds[strTopicSysId] = true;
            }
        }
    }

    for (var topicSysId in topicsSysIds) {
        var grTopic = GetRecord('topic', topicSysId);
        if (IsValidRecord(grTopic) == true) {
            if (GetStringValue(grTopic.sys_scope) == strPackageScope) {
                RecordTransporterRecordPack(grPackage, grTopic);
            }
        }
    }

    return true;
}
